k = input(7, "K Neighbors", 1, 20, 1)
featureBars = input(20, "Feature Bars", 5, 40, 1)
searchBars = input(250, "Search Bars", 20, 500, 5)
marginThresh = input(0.71, "Margin Threshold", 0.14, 1.0, 0.01)
agreeThresh = input(0.35, "Disagreement Max", 0.05, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

var f0Hist = array(0)
var f1Hist = array(0)
var clHist = array(0)

// ─── Per-bar raw features f0, f1 ───
prevC = close[1]
isFirst = bar_index == 0
if isFirst {
    prevC := close
}
denomC = abs(prevC) + 0.000000001
f0 = (close - prevC) / denomC
f1 = (high - low) / (abs(close) + 0.000000001)

array.push(f0Hist, f0)
array.push(f1Hist, f1)
array.push(clHist, close)

n = array.size(clHist)

// ─── KNN search + vote (recomputed every bar) ───
bullVotes = 0
bearVotes = 0
voteMargin = 0.0
disagree = 1.0
signedVote = 0.0

if n > featureBars + 1 {
    bestDist = array()
    bestDir = array()
    bi = 0
    while bi < k {
        array.push(bestDist, 999999.0)
        array.push(bestDir, 0)
        bi := bi + 1
    }

    // earliest j with full feature window and a next bar for label
    lo = n - 1 - searchBars
    if lo < 0 {
        lo := 0
    }
    minJ = featureBars - 1
    if lo < minJ {
        lo := minJ
    }
    hi = n - 2
    curTop = n - 1

    j = lo
    while j <= hi {
        // Euclidean distance over last featureBars of f0,f1
        ssd = 0.0
        b = 0
        while b < featureBars {
            a0 = f0Hist[curTop - b] - f0Hist[j - b]
            a1 = f1Hist[curTop - b] - f1Hist[j - b]
            ssd := ssd + a0 * a0 + a1 * a1
            b := b + 1
        }
        d = sqrt(ssd + 0.000000001)

        // label by neighbour next-bar direction
        c0 = clHist[j]
        c1 = clHist[j + 1]
        lbl = 0 - 1
        if c1 > c0 {
            lbl := 1
        }

        // insertion sort into k smallest
        ins = -1
        m = 0
        while m < k {
            if d < bestDist[m] {
                ins := m
                m := k
            }
            m := m + 1
        }
        if ins >= 0 {
            m = k - 1
            while m > ins {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestDir, m, bestDir[m - 1])
                m := m - 1
            }
            array.set(bestDist, ins, d)
            array.set(bestDir, ins, lbl)
        }
        j := j + 1
    }

    // count votes among filled neighbours
    found = 0
    sumDir = 0
    m = 0
    while m < k {
        if bestDist[m] < 999998.0 {
            found := found + 1
            if bestDir[m] == 1 {
                bullVotes := bullVotes + 1
                sumDir := sumDir + 1
            } else {
                bearVotes := bearVotes + 1
                sumDir := sumDir - 1
            }
        }
        m := m + 1
    }

    if found > 0 {
        // vote margin M = |sum| / found
        mm = abs(sumDir) / found
        voteMargin := mm
        signedVote := sumDir / found

        // distance dispersion: stdev / mean of neighbour distances
        meanD = 0.0
        m = 0
        while m < found {
            meanD := meanD + bestDist[m]
            m := m + 1
        }
        meanD := meanD / found
        varD = 0.0
        m = 0
        while m < found {
            dd = bestDist[m] - meanD
            varD := varD + dd * dd
            m := m + 1
        }
        varD := varD / found
        sdD = sqrt(varD)
        disp = 0.0
        if meanD > 0.000000001 {
            disp := sdD / meanD
        }
        if disp > 1.0 {
            disp := 1.0
        }
        if disp < 0.0 {
            disp := 0.0
        }
        dm = 1.0 - mm
        disagree := (dm + disp) / 2.0
    } else {
        voteMargin := 0.0
        disagree := 1.0
        signedVote := 0.0
    }
}

// ─── Signal conditions: both channels must agree ───
buyCond = bullVotes > bearVotes and voteMargin >= marginThresh and disagree <= agreeThresh
sellCond = bearVotes > bullVotes and voteMargin >= marginThresh and disagree <= agreeThresh
buyPrev = buyCond[1]
sellPrev = sellCond[1]
buySig = buyCond and not buyPrev
sellSig = sellCond and not sellPrev

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
}

// ─── 2D channels: independently readable ───
plot(voteMargin, "Vote Margin", "#22cc88", 2, "separate")
plot(disagree, "Disagreement", "#ff4477", 2, "separate")
plot(signedVote, "Vote Direction", "#ffd43b", 1, "separate")

// ─── 3D form: crisp = tall narrow pillar, contested = short wide slab ───
plot3d(voteMargin, "Margin Pillars", "bars3d", "#22cc88", "separate")
plot3d(disagree, "Disagreement Sheet", "surface", "#ff4477", "separate", 1)

if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate")
}

// Volume Session Value Terrain
// Volume-profile-on-chart: POC + value area from visible session, price leaving value is the signal.

profileRows = input(24, "Profile Rows", 12, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(120, "Visible Session Length", 30, 300, 10)
showHist = input(true, "Show Value Histogram")
enable3D = input(true, "Enable 3D Terrain")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session window range ──────────────────────────────────────────
sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
sessRange = sessHigh - sessLow
if sessRange <= 0 { sessRange := close * 0.01 }
rowH = sessRange / profileRows

// ─── Row volumes: proportional overlap assignment ──────────────────
var rowVol = array()
if array.size(rowVol) == 0 {
    k = 0
    while k < 48 {
        array.push(rowVol, 0.0)
        k := k + 1
    }
}
// reset active rows
i = 0
while i < profileRows {
    array.set(rowVol, i, 0.0)
    i := i + 1
}
// deposit each bar in window into overlapped rows
j = 0
while j < sessLen {
    bHigh = high[j]
    bLow = low[j]
    bVol = volume[j]
    bRange = bHigh - bLow
    if bRange <= 0 {
        // zero-range bar: assign to row containing close
        ci = floor((close[j] - sessLow) / sessRange * profileRows)
        if ci < 0 { ci := 0 }
        if ci > profileRows - 1 { ci := profileRows - 1 }
        array.set(rowVol, ci, array.get(rowVol, ci) + bVol)
    } else {
        i := 0
        while i < profileRows {
            rowTop = sessLow + (i + 1) * rowH
            rowBot = sessLow + i * rowH
            topEdge = bHigh
            if rowTop < topEdge { topEdge := rowTop }
            botEdge = bLow
            if rowBot > botEdge { botEdge := rowBot }
            ov = topEdge - botEdge
            if ov > 0 {
                share = ov / bRange
                array.set(rowVol, i, array.get(rowVol, i) + bVol * share)
            }
            i := i + 1
        }
    }
    j := j + 1
}

// ─── Totals + POC ──────────────────────────────────────────────────
totalVol = 0.0
i = 0
while i < profileRows {
    totalVol := totalVol + array.get(rowVol, i)
    i := i + 1
}
pocRow = 0
pocVol = array.get(rowVol, 0)
i = 1
while i < profileRows {
    v = array.get(rowVol, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocPrice = sessLow + (pocRow + 0.5) * rowH
maxRowVol = pocVol
if maxRowVol <= 0 { maxRowVol := 1.0 }

// ─── Value area expansion from POC ─────────────────────────────────
vaLowRow = pocRow
vaHighRow = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profileRows {
    leftVal = 0 - 1.0
    if vaLowRow > 0 { leftVal := array.get(rowVol, vaLowRow - 1) }
    rightVal = 0 - 1.0
    if vaHighRow < profileRows - 1 { rightVal := array.get(rowVol, vaHighRow + 1) }
    if rightVal >= leftVal and vaHighRow < profileRows - 1 {
        vaHighRow := vaHighRow + 1
        accum := accum + rightVal
    } else {
        if vaLowRow > 0 {
            vaLowRow := vaLowRow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHighRow + 1) * rowH
valPrice = sessLow + vaLowRow * rowH

// ─── Signal conditions (event: leaving value) ──────────────────────
prevInside = close[1] >= valPrice[1] and close[1] <= vahPrice[1]
buySig = crossover(close, vahPrice) and prevInside
sellSig = crossunder(close, valPrice) and prevInside

// ─── Signal markers (2D) ───────────────────────────────────────────
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

// ─── 2D value histogram bars (left from right edge) + zone ─────────
if showHist {
    i = 0
    while i < profileRows {
        rv = array.get(rowVol, i)
        wBars = rv / maxRowVol * sessLen * 0.5
        if wBars < 1 { wBars := 1 }
        rTop = sessLow + (i + 1) * rowH
        rBot = sessLow + i * rowH
        leftB = bar_index - wBars
        rightB = bar_index
        bc = "#4488ff"
        if i == pocRow { bc := "#ffd43b" }
        if i >= vaLowRow and i <= vaHighRow { bc := "#22cc88" }
        if i == pocRow { bc := "#ffd43b" }
        box.new(leftB, rTop, rightB, rBot, bc, bc, 1)
        i := i + 1
    }
}
text.new(bar_index, pocPrice, "POC", "#ffd43b", 1, "pocLbl")
text.new(bar_index, vahPrice, "VAH", "#22cc88", 1, "vahLbl")
text.new(bar_index, valPrice, "VAL", "#ff4477", 1, "valLbl")

// ─── 2D rails (same levels carried when 3D is off) ─────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
fill(vahPrice, valPrice, "rgba(34,204,136,0.10)")

// ─── 3D terrain + labelled POC rail + boundary rails ───────────────
if enable3D {
    plot3d(pocPrice, "Value Terrain", "surface", "#4488ff", "3d", 0)
    plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)
    plot3d(valPrice, "VAL Rail", "line3d", "#ff4477", "3d", 2)
}
if enable3D {
    if buySig { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d") }
    if sellSig { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 2, "3d") }
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 0, "3d")
}

// Fix 1: var lvl = highest(high, 20) froze at bar 0 — changed to plain assignment so it recomputes every bar.
// Fix 2: close[-1] is a future leak — changed to close > lvl for a present-bar breakout.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine signature — changed to OakScript positional (bar_index, price, title, style, color) with quoted style and hex color.
// Fix 4: plot3d(r, ..., "3d") forces an oscillator into the price scene — changed to pane "separate" per PANE LAW.
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1)
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowSrc = input(close, "Flow PSI Source")
critThresh = input(150, "Critical Threshold", 50, 300, 1)
spinFactor = input(1.0, "Spin Factor", 0.1, 5.0, 0.1)
expRate = input(1.0, "Ring Expansion Rate", 0.1, 3.0, 0.1)
maxR = input(10.0, "Ring Max Radius", 4.0, 20.0, 0.5)
perimR = input(2.0, "Disc Perimeter Radius", 1.0, 5.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

spinSpeed = flowSrc * spinFactor
overState = flowSrc > critThresh

var discAngle = 0.0
var lockAngle = 0.0
var baseR = 2.0
var r1 = 2.0
var r2 = 2.0
var r3 = 2.0

breachEvent = overState and not overState[1]
clearEvent = not overState and overState[1]

if breachEvent {
  lockAngle := discAngle[1]
  discAngle := discAngle[1]
  baseR := perimR
  r1 := perimR
  r2 := perimR + 2.0
  r3 := perimR + 4.0
} else {
  if overState {
    discAngle := discAngle[1]
    lockAngle := lockAngle[1]
    baseR := baseR[1] + expRate
    if baseR > maxR {
      baseR := perimR
    }
    r1 := r1[1] + expRate
    if r1 > maxR {
      r1 := perimR
    }
    r2 := r2[1] + expRate
    if r2 > maxR {
      r2 := perimR
    }
    r3 := r3[1] + expRate
    if r3 > maxR {
      r3 := perimR
    }
  } else {
    discAngle := discAngle[1] + spinSpeed
    lockAngle := discAngle
    baseR := perimR
    r1 := perimR
    r2 := perimR
    r3 := perimR
  }
}

spinAnglePlot = discAngle
lockedDiscAngle = lockAngle

if breachEvent {
  plotshape(bar_index, high, "OVERPRESSURE", "triangledown", "#ff4477")
}

if clearEvent {
  plotshape(bar_index, low, "Normalized", "triangleup", "#22cc88")
}

if breachEvent {
  plotshape_3d(bar_index, high, "Valve Lock", "torus", "#ff4477", markerSize, 0, "separate", 90, lockedDiscAngle, 0)
}

if breachEvent {
  plotshape_3d(bar_index, high, "Shock1", "torus", "#ff8833", r1 * 0.15 * markerSize, 1, "separate", 90, lockedDiscAngle, 0)
}

if breachEvent {
  plotshape_3d(bar_index, high, "Shock2", "torus", "#ffcc44", r2 * 0.15 * markerSize, 2, "separate", 90, lockedDiscAngle, 0)
}

if breachEvent {
  plotshape_3d(bar_index, high, "Shock3", "torus", "#ffffff", r3 * 0.15 * markerSize, 3, "separate", 90, lockedDiscAngle, 0)
}

if breachEvent {
  label3d(bar_index, high, "OVERPRESSURE", "#ff4477", 2, 4, "separate")
}

if clearEvent {
  plotshape_3d(bar_index, low, "Valve Free", "torus", "#22cc88", markerSize, 0, "separate", 90, spinAnglePlot, 0)
}

plot(flowSrc, "Flow PSI", "#22cc88", 2)
hline(critThresh, "#ff4477")
plot(spinSpeed, "Spin Speed", "#ffaa00", 1)
plot(spinAnglePlot, "Disc Angle", "#44ccff", 1)
plot3d(flowSrc, "Flow PSI", "ribbon", "#22cc88", "separate")
plot3d(spinSpeed, "Spin Speed", "line3d", "#ffaa00", "separate", 1)
